head.script:
scwin.trigger1_onclick = function(e) { //debugger;
    inputCalendar2.setInputStyle("background-color", "skyblue");
};
scwin.unitTest = function() {
    // debugger;
    // Init test
    WebSquare.wUnit.start();
    // Test step 1: 1. 샘플파일을 실행 후 "setInputStyle"버튼을 클릭한다. - 1. Run the sample file and click the "setInputStyle" button.
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // Verify 1: 1. inputCalendar의 입력창의 색상이 하늘색으로 변경되어진다.(이전에는 기능이 없었음)
    // - 1. The color of the input window of inputCalendar is changed to light blue (previously no function)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('inputCalendar2_input').style.backgroundColor == 'skyblue'", "true");
    // Run test
    WebSquare.wUnit.run();
    // Stop test
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    // Function test
    // Created by Sang.Do
    // Created date 17-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
